<?php
/** Private concurrent new intentions, history and selected-attempt writeback. */
function runMarketDistinctHttp($f,$api,$suffix,$token,$video,$product,$sku,$supplier,array &$report): void
{
    global $urls;
    $db=think\facade\Db::class;$t=$f->tenant;$u=$f->user;$script=dirname(__DIR__).'/market-generation-http.php';
    $check=fn($ok,$message)=>MarketWorkerFixture::check((bool)$ok,$message);
    $post=fn($path,$p)=>dataHttp($api,'/api/app.'.$path.$suffix,$p,$token);
    $get=fn($path,$id)=>dataHttp($api,'/api/app.'.$path.$suffix.'&id='.$id,[],$token,'GET');
    $pair=function($path,$p,$keys)use($api,$urls,$suffix,$token,$check){
        $multi=curl_multi_init();$handles=[];
        foreach([$api,$urls['api_peer']]as$i=>$base){$c=curl_init($base.'/api/app.'.$path.$suffix);curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($p),CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Host: private-media.example.test','token: '.$token,'X-Generation-Request-Key: '.$keys[$i]],CURLOPT_TIMEOUT=>20]);curl_multi_add_handle($multi,$c);$handles[]=$c;}
        do{curl_multi_exec($multi,$active);if($active)curl_multi_select($multi,0.01);}while($active);
        $out=[];foreach($handles as$i=>$c){$r=json_decode((string)curl_multi_getcontent($c),true);curl_multi_remove_handle($multi,$c);curl_close($c);if(($r['generation_submission']['state']??'')==='submitting')$r=callHttp($api,'/api/app.'.$path.$suffix,$p,$token,'POST',['X-Generation-Request-Key: '.$keys[$i]]);$check(($r['code']??0)===1,'Distinct HTTP rejected '.$path.': '.json_encode($r));$out[]=$r['data'];}curl_multi_close($multi);return $out;
    };
    $drain=function($app)use($f,$script,$db){$f->start($script,$app);MarketWorkerFixture::wait(fn()=>$db::name('ai_task_job')->where('status','<>','success')->count()===0,'Distinct result jobs incomplete',40);$f->stop();};
    $native=array_intersect_key($video,array_flip(['resource_type','model_id','market_product_id','market_sku_id','channel','prompt','duration','quality','ratio','generation_method','advanced_params']));
    $key='distinct-original-video-0001';[$first,$same]=$pair('aigc_video.generate/index',$native,[$key,$key]);$check($first['task_id']===$same['task_id'],'Same key created two videos');$drain('aigc_video');
    $history=$get('aigc_video.task/detail',$first['task_id']);$check($history['generation_task']['status']==='success','Original video incomplete');$old=$db::name('aigc_video_task')->where('id',$first['task_id'])->find();
    $other=$u+1;$account=$f->prefix.'other';$db::name('user')->insert(['id'=>$other,'tenant_id'=>$t,'sn'=>$other,'account'=>$account,'nickname'=>'Other fixture owner','password'=>create_password('Private-fixture-pass-2026',config('project.unique_identification')),'user_money'=>100,'create_time'=>time(),'update_time'=>time()]);
    $login=callHttp($api,'/api/login/account'.$suffix,['account'=>$account,'password'=>'Private-fixture-pass-2026','scene'=>1,'terminal'=>4]);$foreign=callHttp($api,'/api/app.aigc_video.generate/index'.$suffix,$native,$login['data']['token'],'POST',['X-Generation-Request-Key: '.$key]);
    $check(($foreign['code']??0)===1&&$foreign['data']['task_id']!==$first['task_id'],'Another user could not independently submit same raw key: '.json_encode($foreign));$report['same_raw_key_different_authenticated_owner']=true;
    $reused=array_replace($native,['prompt'=>$history['prompt'],'ratio'=>$history['ratio'],'quality'=>$history['quality']]);[$a,$b]=$pair('aigc_video.generate/index',$reused,['distinct-history-video-0002','distinct-history-video-0003']);$check(count(array_unique([$first['task_id'],$a['task_id'],$b['task_id']]))===3,'History intentions merged by content');
    $db::name('power_market_sku')->where('id',$sku['id'])->update(['sale_status'=>0,'sale_points'=>99]);$db::name('power_market_product')->where('id',$product['id'])->update(['status'=>0]);$drain('aigc_video');
    foreach([$a,$b]as$r){$d=$get('aigc_video.task/detail',$r['task_id']);$check($d['generation_task']['status']==='success'&&count($d['results'])===1,'History result missing');}
    $check($old===$db::name('aigc_video_task')->where('id',$first['task_id'])->find(),'Old history changed');$check($db::name('ai_consumption_log')->where('user_id',$other)->where('billing_status','settled')->count()===1,'Other user not independently settled once');
    $replay=callHttp($api,'/api/app.aigc_video.generate/index'.$suffix,$native,$token,'POST',['X-Generation-Request-Key: '.$key]);$check($replay['data']===$first,'Shelf change altered acceptance');$db::name('power_market_sku')->where('id',$sku['id'])->update(['sale_status'=>1,'sale_points'=>1]);$db::name('power_market_product')->where('id',$product['id'])->update(['status'=>1]);$report['parallel_native_history_frozen_acceptance_and_old_rows']=true;
    $node=['id'=>'selected-attempt','type'=>'video','position'=>['x'=>0,'y'=>0],'metadata'=>['prompt'=>'Synthetic shared node','status'=>'idle','quality'=>'720P','duration'=>1,'ratio'=>'1:1']];$project=$post('aigc_canvas.project/create',['name'=>'Private distinct canvas','nodes'=>[$node],'edges'=>[],'viewport'=>['x'=>0,'y'=>0,'zoom'=>1]]);
    $input=array_replace($video,['project_id'=>$project['id'],'node_id'=>$node['id'],'prompt'=>'Synthetic shared node']);[$early,$selected]=$pair('aigc_canvas.generate/video',$input,['distinct-canvas-attempt-0004','distinct-canvas-attempt-0005']);$check($early['generation_task']['task_ref']!==$selected['generation_task']['task_ref'],'Canvas intentions merged');
    $node['metadata']=array_replace($node['metadata'],['prompt'=>'Edited draft after acceptance','status'=>'running','pending'=>true,'taskId'=>(string)$selected['task_id'],'generationTaskRef'=>$selected['generation_task']['task_ref'],'generationStartedAt'=>time()*1000,'mediaItems'=>[]]);$post('aigc_canvas.project/save',['id'=>$project['id'],'nodes'=>[$node],'edges'=>[],'viewport'=>$project['viewport']]);$drain('aigc_canvas');
    $view=app\common\service\ai\GenerationTaskResultService::read($selected['generation_task']['app_task_id'],$t,$u);$opened=$get('aigc_canvas.project/detail',$project['id']);$meta=$opened['nodes'][0]['metadata'];$check($meta['status']==='success'&&$meta['generationTaskRef']===$selected['generation_task']['task_ref']&&$meta['uri']===$view['results'][0]['uri']&&$meta['prompt']==='Edited draft after acceptance','Selected canvas result/draft lost');
    $before=$db::name('aigc_canvas_project')->where('id',$project['id'])->find();app\common\service\ai\AiTaskBusinessResultService::syncTerminalByConsumptionId((int)$early['task_id']);$check($before===$db::name('aigc_canvas_project')->where('id',$project['id'])->find(),'Old callback overwrote selected attempt');$runs=dataHttp($api,'/api/app.aigc_canvas.run/lists'.$suffix.'&project_id='.$project['id'],[],$token,'GET');$check(count($runs['lists'])===2,'Canvas attempt history missing');$report['parallel_canvas_selected_writeback_late_old_callback_and_history']=true;
    $db::name('app')->insert(['code'=>'smart_clip','name'=>'Private clip','status'=>'installed','is_builtin'=>1,'current_version'=>'0.0.0','install_time'=>time(),'update_time'=>time()]);$db::name('tenant_app')->insert(['tenant_id'=>$t,'app_code'=>'smart_clip','buy_status'=>'paid','shelf_status'=>'on','enable_status'=>'enabled','create_time'=>time(),'update_time'=>time()]);$db::name('smart_clip_channel')->insert(['tenant_id'=>0,'code'=>'private-clip','name'=>'Private clip','provider'=>'xhadmin','model'=>'smart_clip','status'=>1,'config_json'=>'{}']);$db::name('smart_clip_channel_spec')->insert(['tenant_id'=>0,'channel_code'=>'private-clip','quality'=>'1','quality_label'=>'1秒','ratio'=>'duration','platform_unit_cost'=>1,'tenant_unit_price'=>1,'status'=>1,'provider_params_json'=>'{}']);
    $clip=['api'=>'realman_broadcast','channel'=>'private-clip','styleId'=>'private-template','title'=>'Identical synthetic clip','videoUrl'=>$supplier.'/fixture/result.mp4','audioUrl'=>$supplier.'/fixture/input.wav','materials'=>[['type'=>'video','url'=>$supplier.'/fixture/result.mp4','duration'=>2]],'processRules'=>['videoDuration'=>2],'duration'=>2];[$ca,$cb]=$pair('smart_clip.generate/index',$clip,['distinct-clip-attempt-0006','distinct-clip-attempt-0007']);$check($ca['task_id']!==$cb['task_id'],'Clip intentions merged by title');$db::name('smart_clip_channel')->where('code','private-clip')->update(['status'=>0]);$drain('smart_clip');
    foreach([$ca,$cb]as$r){$d=$get('smart_clip.task/detail',$r['task_id']);$check($d['generation_task']['status']==='success'&&count($d['results'])===1,'Distinct clip incomplete');}$check($db::name('smart_clip_billing')->where('billing_status','deducted')->count()===2,'Clip billing incorrect');$report['parallel_clip_same_content_independent_bills_and_results']=true;
    $post('aigc_video.task/delete',['id'=>$first['task_id']]);$before=$db::name('ai_app_task')->count();$deleted=callHttp($api,'/api/app.aigc_video.generate/index'.$suffix,$native,$token,'POST',['X-Generation-Request-Key: '.$key]);$check($deleted['code']!==1&&$db::name('ai_app_task')->count()===$before,'Deleted retry redispatched');$report['deleted_original_http_retry_not_redispatched']=true;
}
